/**
 * Shared GCP Secrets Manager helpers, used by bruno-electron.
 *
 * The Google SDK is `require`d lazily so importing this module never fails when the optional
 * dependency isn't installed. The client is created in REST (`fallback`) mode so it speaks HTTP:
 * this is load-bearing, not cosmetic — a Node http(s) agent cannot be attached to a gRPC channel,
 * so REST mode is what makes the caller's proxy/TLS config applicable at all.
 */

import { buildResolveAgents } from '../resolve-agents';
import type { ResolveAgents, SecretManagerNetworkConfig } from '../resolve-agents';

export interface GcpSecretManagerConfig {
  // The service account's own project. Secrets are read from the project ids named on the
  // environment's secret rows, so only the credential fields below take part in the fetch.
  projectId?: string;
  clientEmail?: string;
  privateKey?: string;
}

export interface GcpSecretResult {
  projectId: string;
  data?: Record<string, any>;
  error?: string;
}

const CLOUD_PLATFORM_SCOPE = 'https://www.googleapis.com/auth/cloud-platform';

// Build a GoogleAuth for a service account whose requests are routed through the supplied proxy/TLS
// agents, resolved per request URL (so proxy-bypass rules are evaluated against each target — the
// OAuth token endpoint and the Secret Manager endpoint are different hosts).
//
// Unlike the AWS and Azure SDKs, the Google client exposes no `requestHandler`/`httpClient` seam,
// and google-gax overwrites `agent` on every fallback-REST request with its own keep-alive agent —
// so agents supplied as client options or transporter defaults never survive. A gaxios request
// interceptor is the one hook that runs after that overwrite. It is installed on the auth client's
// transporter, which carries both the token exchange and the Secret Manager API calls.
//
// `scopes` is left unset for the fetch path: SecretManagerServiceClient applies its own
// `defaultScopes` to this object while constructing, and passing scopes here would pre-empt them.
// Only the standalone credential check needs to name a scope itself.
const createGcpProxyAuth = (
  gcpConfig: GcpSecretManagerConfig,
  resolveAgents: ResolveAgents,
  scopes?: string[]
) => {
  // Both fields are required to mint the signed JWT. Without this guard the Google SDK reports the
  // gap in its own vocabulary ("The incoming JSON object does not contain a client_email field"),
  // which is opaque to a user who supplied the values through the CLI's --secrets-env-file — a path
  // with no form validation behind it.
  const clientEmail = gcpConfig?.clientEmail?.trim();
  const privateKey = gcpConfig?.privateKey?.trim();
  if (!clientEmail || !privateKey) {
    throw new Error('GCP service account requires both a client email and a private key');
  }

  const { GoogleAuth, gaxios } = require('google-auth-library');
  const transporter = new gaxios.Gaxios();
  transporter.interceptors.request.add({
    resolved: async (config: any) => {
      const url = new URL(config.url);
      const { httpAgent, httpsAgent } = await resolveAgents(url.toString());
      const agent = url.protocol === 'https:' ? httpsAgent : httpAgent;
      if (agent) config.agent = agent;
      return config;
    }
  });

  // The transporter is handed over as a client option rather than applied to an eagerly created
  // client: SecretManagerServiceClient sets `defaultScopes`/`useJWTAccessWithScope` on this object
  // while constructing, so the underlying JWT must stay lazy to be scoped correctly.
  return new GoogleAuth({
    credentials: {
      client_email: clientEmail,
      private_key: privateKey
    },
    clientOptions: { transporter },
    ...(scopes ? { scopes } : {})
  });
};

// The client is project-agnostic: every call below names its project in a fully qualified resource
// string, so a single client serves every requested project.
const buildGcpClient = (gcpConfig: GcpSecretManagerConfig, resolveAgents: ResolveAgents) => {
  const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
  return new SecretManagerServiceClient({
    auth: createGcpProxyAuth(gcpConfig, resolveAgents),
    // REST rather than gRPC so the interceptor's http(s) agent can apply at all — see module header.
    fallback: 'rest'
  });
};

// JSON payloads are parsed so callers can reach individual fields (`<namespace>.<secret>.<key>`);
// anything that doesn't parse is passed through as the raw string.
const accessSecretValue = async (client: any, projectId: string, secretName: string): Promise<any> => {
  const [version] = await client.accessSecretVersion({
    name: `projects/${projectId}/secrets/${secretName}/versions/latest`
  });
  const payload = version?.payload?.data;
  const raw = payload ? Buffer.from(payload).toString('utf8') : '';
  try {
    return JSON.parse(raw);
  } catch (_) {
    return raw;
  }
};

// Project IDs are interpolated into `projects/<id>/secrets/...` (a URL path in fallback REST
// mode), so we validate GCP's structural project ID rules (or allow a numeric project number)
// to prevent path rewriting. Other GCP constraints are left to the API. Legacy domain-scoped
// IDs (e.g. `example.com:my-project`) are also path-safe and supported.
const GCP_PROJECT_ID_REGEX = /^(?:[a-z0-9-]+(?:\.[a-z0-9-]+)+:)?(?:[a-z][a-z0-9-]{4,28}[a-z0-9]|\d{6,30})$/;

// List every secret id in the project, paginating through all pages.
const listAllSecretNames = async (client: any, projectId: string): Promise<string[]> => {
  const names: string[] = [];
  const iterable = client.listSecretsAsync({ parent: `projects/${projectId}` });
  for await (const secret of iterable) {
    const name = secret?.name?.split('/').pop();
    if (name) names.push(name);
  }
  return names;
};

// A project can hold thousands of secrets, and every one costs a separate API call. Reading them
// all at once would burst past Secret Manager's request quota and exhaust sockets, so reads run
// through a fixed pool of workers instead.
const MAX_CONCURRENT_SECRET_READS = 10;

// Read every secret in one project, keyed by secret id. An individual unreadable secret is skipped
// rather than costing the caller the whole project; a failure to list the project propagates so it
// can surface as that project's error.
const fetchProjectSecrets = async (client: any, projectId: string): Promise<Record<string, any>> => {
  const secretNames = await listAllSecretNames(client, projectId);

  const data: Record<string, any> = {};
  let nextIndex = 0;
  const worker = async () => {
    while (nextIndex < secretNames.length) {
      const secretName = secretNames[nextIndex++];
      try {
        data[secretName] = await accessSecretValue(client, projectId, secretName);
      } catch (_) {
        // Skipped rather than failing the project — but the reason matters when a user reports
        // empty variables. The usual causes are a disabled or destroyed latest version, and a
        // service account that can list secrets but not access their versions.
      }
    }
  };
  const workerCount = Math.min(MAX_CONCURRENT_SECRET_READS, secretNames.length);
  await Promise.all(Array.from({ length: workerCount }, worker));

  return data;
};

// Fetch every secret from each requested GCP project. No per-secret ids are supplied: a project's
// secrets are nested under the caller's row name (accessed as `<name>.<secretId>`). Errors are
// returned per project so one failing project doesn't abort the rest; an account-level problem
// (incomplete credentials) rejects the whole call instead, since it isn't attributable to a project.
export const fetchGcpSecretsManagerSecrets = async ({
  gcpConfig,
  projectIds,
  networkConfig
}: {
  gcpConfig: GcpSecretManagerConfig;
  projectIds: string[];
  networkConfig?: SecretManagerNetworkConfig;
}): Promise<GcpSecretResult[]> => {
  // The client is deliberately not closed: in fallback-REST mode there is no gRPC channel to tear
  // down, and the sockets belong to the shared cached agents behind `getHttpHttpsAgents`, not to
  // this client — closing it would release nothing. Dropping `fallback: 'rest'` would make closing
  // mandatory.
  const client = buildGcpClient(gcpConfig, buildResolveAgents(networkConfig));

  // Projects are read one at a time so the worker pool inside fetchProjectSecrets stays the overall
  // concurrency ceiling; fanning out over projects would multiply it by the number of projects.
  const results: GcpSecretResult[] = [];
  // Project ids arrive from user-entered table rows (and variable interpolation), so surrounding
  // whitespace is common and would otherwise fail the id validation below.
  for (const rawProjectId of projectIds || []) {
    const projectId = (rawProjectId || '').trim();
    if (!GCP_PROJECT_ID_REGEX.test(projectId)) {
      results.push({ projectId, error: 'Invalid GCP project id' });
      continue;
    }

    try {
      results.push({ projectId, data: await fetchProjectSecrets(client, projectId) });
    } catch (error: any) {
      results.push({ projectId, error: error?.message || 'Unknown error' });
    }
  }

  return results;
};

export const gcpWhoami = async ({
  config,
  networkConfig
}: {
  config: { gcpConfig: GcpSecretManagerConfig };
  networkConfig?: SecretManagerNetworkConfig;
}): Promise<{ status: string; message: string }> => {
  try {
    // Project ids live on the environment's secret rows, not on the account, so there is no project
    // to probe here. Minting an access token runs the full signed-JWT exchange, which is what proves
    // the service-account credentials themselves are usable.
    const auth = createGcpProxyAuth(config.gcpConfig, buildResolveAgents(networkConfig), [CLOUD_PLATFORM_SCOPE]);
    const client = await auth.getClient();
    const { token } = await client.getAccessToken();
    if (!token) {
      throw new Error('No access token was returned for these credentials');
    }
    return { status: 'success', message: 'GCP credentials are valid' };
  } catch (error: any) {
    throw new Error(error?.message || 'Failed to validate GCP credentials');
  }
};
